mapper.sql:
WHERE customer_contacts.is_active = 1

    AND customers.id IN (
    SELECT customer_id
    FROM customer_cgroups
    WHERE cgroup_id IN (
    SELECT cgroup_id
    FROM cgroup_egroups
    WHERE egroup_id IN (
    SELECT egroup_id
    FROM employee_egroups
    WHERE employee_id = #{employeeId}
    )
    )
    )


    AND customers.id IN (
    SELECT customer_id
    FROM cgroups
    INNER JOIN customer_cgroups ON cgroups.id = customer_cgroups.cgroup_id
    WHERE cgroups.is_active = 1
    AND (
    cgroups.user_apply = 0
    OR (
    cgroups.user_apply = 1
    AND cgroups.id IN (
    SELECT cgroup_id
    FROM user_cgroups
    WHERE user_id = #{userId}
    )
    )
    )
    )
    AND customers.id IN (
    SELECT customer_id
    FROM customer_companies
    WHERE company_id IN (
    SELECT company_id
    FROM user_companies
    WHERE user_id = #{userId}
    )
    )


    AND customers.id = #{filter.organizationId}


    AND (
        customer_contacts.contact_name LIKE CONCAT("%", #{filter.searchText}, "%")
        OR customer_contacts.contact_email LIKE CONCAT("%", #{filter.searchText}, "%")
        OR customers.name LIKE CONCAT("%", #{filter.searchText}, "%")
     )

mapper.select:
SELECT



ORDER BY


        ${filter.orderBy}


        customer_contacts.contact_name ASC



    LIMIT #{filter.page}, #{filter.rowsPerPage}

SELECT COUNT(id)
FROM customer_contacts
WHERE is_active = 1 AND contact_name = #{name}
 AND id != #{id}
